<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getPopoverContext } from '../popover/popover-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; disabled?: boolean; ref?: HTMLDivElement | null; } let { children, disabled = false, ref = $bindable(null), onpointerenter, onkeydown, ...rest }: Props = $props(); const submenu = getPopoverContext(); $effect.pre(() => { submenu.trigger = ref; }); function enter(event: PointerEvent) { onpointerenter?.(event as PointerEvent & { currentTarget: EventTarget & HTMLDivElement }); if (!disabled && !event.defaultPrevented) submenu.setOpen(true, 'trigger-press', event); } function key(event: KeyboardEvent) { onkeydown?.(event as KeyboardEvent & { currentTarget: EventTarget & HTMLDivElement }); if (!disabled && event.key === 'ArrowRight') { event.preventDefault(); submenu.setOpen(true, 'trigger-press', event); } }</script>
<div bind:this={ref} {...rest} role="menuitem" tabindex="-1" aria-haspopup="menu" aria-expanded={submenu.open} aria-disabled={disabled || undefined} data-popup-open={submenu.open ? '' : undefined} onpointerenter={enter} onkeydown={key}>{@render children?.()}</div>
